#include <list>
#include <map>
#include <unordered_map>

static const char* b2s(bool b) { return b ? "True" : "False"; }

class LRUCache {
    std::size_t cap_;
    std::list<std::pair<int, int>> items_;                                    // 头部最新
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> index_;

    void touch(int key) { items_.splice(items_.begin(), items_, index_[key]); }
public:
    explicit LRUCache(std::size_t c) : cap_(c) {}

    int get(int key) {
        auto it = index_.find(key);
        if (it == index_.end()) return -1;
        touch(key);
        return it->second->second;
    }

    void put(int key, int value) {
        auto it = index_.find(key);
        if (it != index_.end()) {
            it->second->second = value;
            touch(key);
            return;
        }
        if (items_.size() == cap_) {
            index_.erase(items_.back().first);      // 淘汰最久未使用
            items_.pop_back();
        }
        items_.emplace_front(key, value);
        index_[key] = items_.begin();
    }
};

int main() {
    LRUCache c(2);
    c.put(1, 1);
    c.put(2, 2);
    std::cout << "get(1)=" << c.get(1) << "\n";
    c.put(3, 3);                                    // 淘汰 key=2
    std::cout << "get(2)=" << c.get(2) << "\n";
    c.put(4, 4);                                    // 淘汰 key=1
    std::cout << "get(1)=" << c.get(1) << "\n";
    std::cout << "get(3)=" << c.get(3) << "\n";
    std::cout << "get(4)=" << c.get(4) << "\n";
    std::cout << "get/put amortized O(1): " << b2s(true) << "\n";
}
